long long minCost(int n, vector<int>& cuts) {
    vector<long long> c{0}; for (int x : cuts) c.push_back(x); c.push_back(n); sort(c.begin(), c.end()); int m = c.size();
    vector<vector<long long>> dp(m, vector<long long>(m, 0));
    for (int len = 2; len < m; len++) for (int i = 0; i + len < m; i++) { int j = i + len; long long b = LLONG_MAX; for (int k = i + 1; k < j; k++) b = min(b, dp[i][k] + dp[k][j]); dp[i][j] = b + c[j] - c[i]; }
    return dp[0][m - 1];
}
